var length2 = new Length("1in");
bool result = length1 > length2; // true

var length1 = new Length("1in");
var length2 = new Length("1in");
bool result = length1 >= length2; // true

var length1 = new Length("1in");
var length2 = new Length("2in");
bool result = length1 < length2; // true

